'use strict';
/* Module 7 enhancement: two new lessons (7.4 Figural & Spatial, 7.6 Classic Psikotes), the
   renumbering map, Lab presets for every lesson's tool block, and the additions the brief
   asks for in the existing lessons (router section in 7.1, P vs Q and letter-series drills in
   7.2, syllogism table and analytic games in 7.3, AKHLAK/BerAKHLAK side by side in 7.5,
   CAT pacing and guessing rows in 7.7, "choose Nadia's track" in 7.8). */
const { b, sec, flow, cmp, scen, step, mist, gl, chk, tool, take, res, rf, lesson, dur, NOTICE } = require('./h');

const RENUMBER = { '7.4': '7.5', '7.5': '7.7', '7.6': '7.8' };

const L74 = lesson({
  n: '7.4', kind: 'interactive', dur: dur(50),
  title: b('Figural and Spatial Reasoning', 'Penalaran Figural dan Spasial'),
  overview: b('Figural items are the family most graduates have never practised and the one where familiarity pays fastest. This lesson names the five figural families used in Indonesian and international batteries, gives one attribute method that solves all of them, settles the rotation and mirror conventions, and drills each family on original Metanoia figures in the Test Lab.', 'Soal figural adalah keluarga yang paling jarang dilatih lulusan dan keluarga tempat keakraban paling cepat terbayar. Pelajaran ini menamai lima keluarga figural yang dipakai baterai tes Indonesia dan internasional, memberi satu metode atribut yang menyelesaikan semuanya, menetapkan konvensi putaran dan cermin, dan melatih tiap keluarga pada gambar asli Metanoia di Test Lab.'),
  objectives: [b('Name the five figural families and recognise each from one example.', 'Menyebutkan lima keluarga figural dan mengenali masing-masing dari satu contoh.'), b('Apply the attribute method: orientation, count, shading, position, size.', 'Menerapkan metode atribut: arah, jumlah, isi, posisi, ukuran.'), b('Tell a rotation from a mirror image in under ten seconds.', 'Membedakan putaran dari bayangan cermin dalam kurang dari sepuluh detik.'), b('Read a cube net and name opposite faces without folding it in your head.', 'Membaca jaring kubus dan menyebut sisi yang berhadapan tanpa melipatnya dalam kepala.')],
  readFirst: rf('Five families, one method', 'Lima keluarga, satu metode', 'The whole figural lesson in four lines.', 'Seluruh pelajaran figural dalam empat baris.', [
    ['Five families', 'Lima keluarga', [['Series, analogy, odd-one-out, matrix, spatial: every figural item is one of these.', 'Deret, analogi, beda gambar, matriks, spasial: setiap soal figural adalah salah satunya.'], ['Name the family first; it tells you what to look for.', 'Sebutkan keluarganya dulu; itu memberi tahu apa yang harus dicari.']]],
    ['One method', 'Satu metode', [['Check attributes one at a time: orientation, count, shading, position, size.', 'Periksa atribut satu per satu: arah, jumlah, isi, posisi, ukuran.'], ['Solve one attribute, cross out the options that break it, then solve the next.', 'Pecahkan satu atribut, coret opsi yang melanggarnya, lalu pecahkan atribut berikutnya.']]],
    ['Rotation is not reflection', 'Putaran bukan cermin', [['Rotation keeps the clockwise order of a figure’s features; a mirror reverses it.', 'Putaran menjaga urutan searah jarum jam dari ciri-ciri gambar; cermin membaliknya.'], ['The most common figural distractor is a mirror image where a rotation is wanted.', 'Pengecoh figural paling umum adalah bayangan cermin ketika yang diminta putaran.']]],
    ['Nets fold by rule', 'Jaring dilipat dengan aturan', [['In a cube net, two cells separated by one cell in a straight line are opposite faces.', 'Pada jaring kubus, dua kotak yang terpisah satu kotak dalam satu garis lurus adalah sisi yang berhadapan.'], ['Adjacent cells are never opposite.', 'Kotak yang bersebelahan tidak pernah berhadapan.']]]
  ]),
  sections: [
    sec('layers', 'The five figural families', 'Lima keluarga figural', 'Every figural item a graduate meets belongs to one of five families. A <b>series</b> shows four or five frames and asks for the next; something changes by a rule each step. An <b>analogy</b> shows A, B and C and asks for D so that A is to B as C is to D; one transformation is applied twice. An <b>odd-one-out</b> shows five figures of which four share a rule. A <b>matrix</b> is a 3×3 grid with one cell missing; rows and columns each carry a rule. <b>Spatial</b> items ask what a figure looks like rotated, reflected, folded or seen from another side. Indonesian batteries use all five; the SKD TIU uses analogy, odd-one-out (“ketidaksamaan”) and series (“serial”); BUMN TKD sets and TPA tests add matrices and nets.', 'Setiap soal figural yang ditemui lulusan termasuk salah satu dari lima keluarga. <b>Deret</b> menampilkan empat atau lima gambar dan meminta gambar berikutnya; sesuatu berubah menurut aturan di tiap langkah. <b>Analogi</b> menampilkan A, B, dan C lalu meminta D sehingga A terhadap B seperti C terhadap D; satu transformasi diterapkan dua kali. <b>Beda gambar</b> menampilkan lima gambar yang empat di antaranya berbagi satu aturan. <b>Matriks</b> adalah kisi 3×3 dengan satu sel kosong; baris dan kolom masing-masing membawa aturan. Soal <b>spasial</b> menanyakan rupa gambar setelah diputar, dicerminkan, dilipat, atau dilihat dari sisi lain. Baterai tes Indonesia memakai kelimanya; TIU SKD memakai analogi, ketidaksamaan, dan serial; set TKD BUMN dan TPA menambahkan matriks dan jaring.'),
    sec('eye', 'The attribute method', 'Metode atribut', 'Figures are not pictures; they are bundles of attributes. Read them in a fixed order: <b>orientation</b> (which way does it point, and by how many degrees does it turn each step), <b>count</b> (how many elements, dots, sides), <b>shading</b> (empty, patterned, solid, and in which cycle), <b>position</b> (where inside the frame, moving which way), <b>size</b> (growing, shrinking, swapping). Write the rule for each attribute on your scrap paper as a tiny table. Then eliminate: every option that breaks the orientation rule goes first, then the count rule, and so on. On most items two attributes already leave one option standing. The order matters because orientation is the attribute distractors abuse most.', 'Gambar bukan lukisan; gambar adalah kumpulan atribut. Bacalah dalam urutan tetap: <b>arah</b> (menghadap ke mana, dan berapa derajat berputar tiap langkah), <b>jumlah</b> (berapa unsur, titik, sisi), <b>isi</b> (kosong, berpola, penuh, dan dalam siklus apa), <b>posisi</b> (di mana dalam bingkai, bergerak ke mana), <b>ukuran</b> (membesar, mengecil, bertukar). Tulis aturan tiap atribut di kertas coret sebagai tabel kecil. Lalu eliminasi: setiap opsi yang melanggar aturan arah dicoret dulu, lalu aturan jumlah, dan seterusnya. Pada kebanyakan soal, dua atribut sudah menyisakan satu opsi. Urutannya penting karena arah adalah atribut yang paling sering dimanfaatkan pengecoh.'),
    sec('refresh', 'Rotation conventions', 'Konvensi putaran', 'Series rotate in steps of 45°, 90° or 180°, almost never anything else. Decide the direction from frames 1 and 2 only: clockwise or anticlockwise. Then confirm on frames 2 and 3, because a figure with two-fold symmetry (a rectangle, an S) looks the same after 180°, which hides the direction. A quarter turn clockwise moves the top to the right; a quarter turn anticlockwise moves the top to the left. Say it aloud once: “top goes right”. Distractors offer the right figure turned the wrong way, or turned one step too far.', 'Deret berputar dengan langkah 45°, 90°, atau 180°, hampir tidak pernah yang lain. Tentukan arahnya hanya dari gambar 1 dan 2: searah atau berlawanan jarum jam. Lalu pastikan pada gambar 2 dan 3, karena gambar dengan simetri lipat dua (persegi panjang, huruf S) tampak sama setelah 180°, yang menyembunyikan arahnya. Seperempat putaran searah jarum jam memindahkan bagian atas ke kanan; seperempat putaran berlawanan memindahkannya ke kiri. Ucapkan sekali: “atas ke kanan”. Pengecoh menawarkan gambar yang benar diputar ke arah yang salah, atau diputar satu langkah terlalu jauh.'),
    sec('x', 'Mirror versus rotation', 'Cermin versus putaran', 'The single most valuable figural skill: a <b>rotation</b> preserves the clockwise order of a figure’s features; a <b>reflection</b> reverses it. Pick two distinctive features of the figure (a dot and a notch, a short arm and a long arm) and ask: going clockwise from feature 1, do I meet feature 2 before or after going half-way round? A rotation gives the same answer; a mirror flips it. This takes under ten seconds and defeats the commonest distractor in series, analogy and spatial items. Rule of thumb: if an option “looks right but something is off”, it is usually the mirror.', 'Keterampilan figural yang paling berharga: <b>putaran</b> mempertahankan urutan searah jarum jam dari ciri-ciri gambar; <b>cermin</b> membaliknya. Pilih dua ciri khas gambar (titik dan lekukan, lengan pendek dan lengan panjang) lalu tanyakan: bergerak searah jarum jam dari ciri 1, apakah ciri 2 ditemui sebelum atau sesudah setengah putaran? Putaran memberi jawaban yang sama; cermin membaliknya. Ini memakan waktu kurang dari sepuluh detik dan mengalahkan pengecoh paling umum di soal deret, analogi, dan spasial. Aturan praktis: jika sebuah opsi “tampak benar tetapi ada yang janggal”, biasanya itu cerminnya.'),
    sec('cube', 'Net folding without folding', 'Melipat jaring tanpa melipat', 'Cube nets come in eleven shapes, but one rule answers most questions: in any straight line of three cells, the two end cells are <b>opposite</b> faces. The middle cell is adjacent to both. Cells that touch along an edge are adjacent and can never be opposite. So for “which face is opposite X”, find the straight run of three that contains X; if there is none, pair up the other faces first and X is opposite whatever is left. Questions that show a folded cube with three visible faces and ask which net it came from use the same rule in reverse: the three visible faces are mutually adjacent, so none of them may be opposite another in the net.', 'Jaring kubus ada sebelas bentuk, tetapi satu aturan menjawab kebanyakan soal: dalam garis lurus tiga kotak, dua kotak ujung adalah sisi yang <b>berhadapan</b>. Kotak tengah bersebelahan dengan keduanya. Kotak yang bersentuhan pada satu sisi bersebelahan dan tidak pernah berhadapan. Jadi untuk “sisi mana yang berhadapan dengan X”, cari garis lurus tiga kotak yang memuat X; jika tidak ada, pasangkan sisi-sisi lain dulu dan X berhadapan dengan yang tersisa. Soal yang menampilkan kubus terlipat dengan tiga sisi terlihat dan menanyakan jaring asalnya memakai aturan yang sama secara terbalik: tiga sisi yang terlihat saling bersebelahan, sehingga tidak boleh ada yang berhadapan dalam jaring.'),
    sec('clock', 'Pace and the figural trap', 'Tempo dan jebakan figural', 'Figural items feel slow because the eye wants to “see” the answer. Budget 40 to 60 seconds, and spend the first ten writing the attribute table. If after one attribute three options remain, solve a second; never stare. Flag any item still open at 75 seconds and move on. In the Lab, the figural drills score the first attribute you check; after fifty items the method becomes automatic and your time per item drops by a third.', 'Soal figural terasa lambat karena mata ingin “melihat” jawabannya. Anggarkan 40 sampai 60 detik, dan pakai sepuluh detik pertama untuk menulis tabel atribut. Jika setelah satu atribut masih tersisa tiga opsi, pecahkan atribut kedua; jangan pernah menatap. Tandai soal yang masih terbuka pada detik ke-75 dan lanjutkan. Di Lab, latihan figural mencatat atribut pertama yang kamu periksa; setelah lima puluh soal metodenya menjadi otomatis dan waktu per soal turun sepertiga.')
  ],
  diagram: flow('Exhibit 1: The attribute method', 'Peraga 1: Metode atribut', 'Five attributes, checked in order, each one crossing out options', 'Lima atribut, diperiksa berurutan, masing-masing mencoret opsi', [
    ['refresh', 'Orientation', 'Arah', 'Direction and degrees per step; mirror or rotation.', 'Arah dan derajat per langkah; cermin atau putaran.'],
    ['list', 'Count', 'Jumlah', 'Elements, dots, sides; cycles of 1-2-3 or growing by one.', 'Unsur, titik, sisi; siklus 1-2-3 atau bertambah satu.'],
    ['palette', 'Shading', 'Isi', 'Empty, pattern, solid; alternating or cycling.', 'Kosong, pola, penuh; bergantian atau bersiklus.'],
    ['target', 'Position', 'Posisi', 'Where in the frame, moving corner to corner.', 'Di mana dalam bingkai, bergerak sudut ke sudut.'],
    ['cube', 'Size', 'Ukuran', 'Growing, shrinking, inner and outer swapping.', 'Membesar, mengecil, dalam dan luar bertukar.']
  ]),
  compare: [cmp('Two ways to meet a series', 'Dua cara menghadapi deret', 'Four frames: an L-shape with a dot, turning each frame.', 'Empat gambar: bentuk L dengan titik, berputar di tiap gambar.', 'Looks at all five options, picks the one that “feels” next. Chooses the mirror image, which has the dot on the wrong side. Thirty seconds wasted and the item wrong.', 'Melihat kelima opsi, memilih yang “terasa” berikutnya. Memilih bayangan cermin, yang titiknya di sisi yang salah. Tiga puluh detik terbuang dan soalnya salah.', 'Writes “turn: 90° clockwise, dot stays at the end of the short arm”. Crosses out two options that turn the wrong way, one that mirrors, one that moves the dot. One left, twenty seconds.', 'Menulis “putar: 90° searah jarum jam, titik tetap di ujung lengan pendek”. Mencoret dua opsi yang berputar ke arah yang salah, satu yang bercermin, satu yang memindahkan titik. Tersisa satu, dua puluh detik.', 'The rule written down is what eliminates the mirror; the eye alone cannot.', 'Aturan yang ditulislah yang menyingkirkan cermin; mata saja tidak bisa.')],
  scenario: scen('eye', 'In focus: twelve items, nine mirrors', 'Sorotan: dua belas soal, sembilan cermin', [['Nadia’s first figural set in the Lab: 5 of 12. The review screen tags nine of her seven misses as “mirror chosen where rotation wanted”. She had never heard the distinction. After the ten-second feature test and two drills of twelve, her next set is 10 of 12, and her time per item has not risen.', 'Set figural pertama Nadia di Lab: 5 dari 12. Layar tinjauan menandai tujuh kesalahannya, sembilan di antaranya tanda “cermin dipilih ketika yang diminta putaran”. Ia belum pernah mendengar perbedaannya. Setelah uji ciri sepuluh detik dan dua latihan dua belas soal, set berikutnya 10 dari 12, dan waktu per soalnya tidak naik.'], ['The figural family is where a week of practice moves a sub-test from below the bar to comfortably above it, because the errors are habits of looking, not of thinking.', 'Keluarga figural adalah tempat satu minggu latihan memindahkan sub-tes dari bawah batas ke cukup jauh di atasnya, karena kesalahannya adalah kebiasaan melihat, bukan berpikir.']]),
  steps: [
    step('Drill 1 · Series: write the table', 'Latihan 1 · Deret: tulis tabelnya', 'Open the Lab’s figural series drill. For each of six items, write the attribute table (orientation, count, shading) before looking at the options, then eliminate.', 'Buka latihan deret figural di Lab. Untuk tiap dari enam soal, tulis tabel atribut (arah, jumlah, isi) sebelum melihat opsi, lalu eliminasi.', 'The Lab’s review names which attribute each distractor breaks. If your misses cluster on one attribute, that attribute goes first in your order from now on.', 'Tinjauan Lab menyebut atribut mana yang dilanggar tiap pengecoh. Jika kesalahanmu menumpuk pada satu atribut, atribut itu diperiksa pertama mulai sekarang.'),
    step('Drill 2 · Analogy: say the transformation', 'Latihan 2 · Analogi: ucapkan transformasinya', 'Six analogy items. Before the options, say the A to B change in words (“rotate 90°, fill becomes dotted”), then apply the same words to C.', 'Enam soal analogi. Sebelum opsi, ucapkan perubahan A ke B dengan kata (“putar 90°, isi menjadi bertitik”), lalu terapkan kata yang sama pada C.', 'Options that apply only part of the change, or apply it to A instead of C, are the designed distractors; the sentence beats both.', 'Opsi yang hanya menerapkan sebagian perubahan, atau menerapkannya pada A alih-alih C, adalah pengecoh yang dirancang; kalimatnya mengalahkan keduanya.'),
    step('Drill 3 · Mirror or rotation', 'Latihan 3 · Cermin atau putaran', 'Twelve rapid spatial items: for each, name two features, run the clockwise test, answer. Target 15 seconds each.', 'Dua belas soal spasial cepat: untuk tiap soal, sebutkan dua ciri, jalankan uji searah jarum jam, jawab. Target 15 detik per soal.', 'Rotation keeps the clockwise order; a mirror flips it. If you missed any, you skipped the test and trusted the eye.', 'Putaran menjaga urutan searah jarum jam; cermin membaliknya. Jika ada yang salah, kamu melewatkan ujinya dan memercayai mata.'),
    step('Drill 4 · Matrices and nets', 'Latihan 4 · Matriks dan jaring', 'Four matrices (row rule, then column rule, then the cell that satisfies both) and four cube nets (find the straight run of three).', 'Empat matriks (aturan baris, lalu aturan kolom, lalu sel yang memenuhi keduanya) dan empat jaring kubus (cari garis lurus tiga kotak).', 'Matrix distractors satisfy one rule only; net distractors are the adjacent faces. Both fall to the written rule.', 'Pengecoh matriks hanya memenuhi satu aturan; pengecoh jaring adalah sisi yang bersebelahan. Keduanya kalah oleh aturan yang ditulis.')
  ],
  mistakes: mist([['Looking at the options first', 'Melihat opsi lebih dulu', 'Table first; options are for crossing out, not for inspiration.', 'Tabel dulu; opsi untuk dicoret, bukan untuk ilham.'], ['Trusting “it looks right”', 'Memercayai “kelihatannya benar”', 'Run the clockwise feature test; the mirror always looks right.', 'Jalankan uji ciri searah jarum jam; cermin selalu kelihatan benar.'], ['Reading direction from one pair of frames', 'Membaca arah dari satu pasang gambar', 'Confirm on a second pair; symmetric shapes hide direction.', 'Pastikan pada pasangan kedua; bentuk simetris menyembunyikan arah.'], ['Folding the net in your head', 'Melipat jaring di kepala', 'Use the straight-run-of-three rule; the head is for harder things.', 'Pakai aturan garis lurus tiga kotak; kepala untuk hal yang lebih sulit.']]),
  glossary: gl([['Series (deret gambar)', 'Deret gambar', 'Frames that change by a rule; find the next.', 'Gambar-gambar yang berubah menurut aturan; cari yang berikutnya.'], ['Figural analogy', 'Analogi gambar', 'A : B :: C : D with one transformation applied twice.', 'A : B :: C : D dengan satu transformasi diterapkan dua kali.'], ['Odd one out (ketidaksamaan)', 'Beda gambar (ketidaksamaan)', 'Five figures, four share a rule; find the one that does not.', 'Lima gambar, empat berbagi aturan; cari yang tidak.'], ['Matrix', 'Matriks', 'A 3×3 grid with row and column rules and one missing cell.', 'Kisi 3×3 dengan aturan baris dan kolom dan satu sel kosong.'], ['Rotation', 'Putaran', 'Turning about a point; preserves clockwise order of features.', 'Berputar pada satu titik; menjaga urutan ciri searah jarum jam.'], ['Reflection (mirror)', 'Cermin', 'Flipping across a line; reverses clockwise order.', 'Membalik pada satu garis; membalik urutan searah jarum jam.'], ['Net', 'Jaring', 'A cube unfolded; opposite faces are two cells apart in a straight line.', 'Kubus yang dibuka; sisi berhadapan terpisah dua kotak dalam garis lurus.']]),
  checks: [
    chk('A figure turns 90° clockwise each frame. Which option is the designed distractor most people choose?', 'Sebuah gambar berputar 90° searah jarum jam tiap gambar. Opsi mana pengecoh rancangan yang paling sering dipilih?', [['The correct figure turned 90° anticlockwise', 'Gambar yang benar diputar 90° berlawanan jarum jam'], ['The mirror image of the correct figure', 'Bayangan cermin dari gambar yang benar'], ['A figure with one more dot', 'Gambar dengan satu titik lebih banyak'], ['The first frame repeated', 'Gambar pertama diulang']], 1, 'The mirror passes the eye test and fails only the clockwise feature test.', 'Cermin lolos uji mata dan hanya gagal pada uji ciri searah jarum jam.'),
    chk('In a cube net, faces that are opposite each other are …', 'Pada jaring kubus, sisi yang saling berhadapan adalah …', [['always adjacent in the net', 'selalu bersebelahan dalam jaring'], ['two cells apart in a straight line', 'terpisah dua kotak dalam garis lurus'], ['the first and last cells of the net', 'kotak pertama dan terakhir jaring'], ['impossible to tell without folding', 'tidak bisa diketahui tanpa melipat']], 1, 'The straight-run-of-three rule; adjacent cells are never opposite.', 'Aturan garis lurus tiga kotak; kotak bersebelahan tidak pernah berhadapan.'),
    chk('The attribute method says to check orientation first because …', 'Metode atribut menyarankan memeriksa arah lebih dulu karena …', [['it is the easiest attribute', 'itu atribut termudah'], ['distractors abuse it most, so it crosses out the most options', 'pengecoh paling sering memanfaatkannya, sehingga paling banyak mencoret opsi'], ['count never changes', 'jumlah tidak pernah berubah'], ['shading is unreliable on screen', 'isi tidak dapat diandalkan di layar']], 1, 'Orientation (including the mirror) is where most designed distractors live.', 'Arah (termasuk cermin) adalah tempat kebanyakan pengecoh rancangan berada.')
  ],
  tool: tool('drill:figural', 'Figural drills in the Test Lab', 'Latihan figural di Test Lab', 'Four drills, one per family group, on original Metanoia figures: series, analogy, odd-one-out and matrices, then rotation, mirror and nets. Untimed first with the attribute table on paper; the review names the attribute each distractor breaks. Then one timed set of twelve. Record your figural percentage as part of your baseline profile in the Dossier.', 'Empat latihan, satu per kelompok keluarga, pada gambar asli Metanoia: deret, analogi, beda gambar, dan matriks, lalu putaran, cermin, dan jaring. Tanpa batas waktu dulu dengan tabel atribut di kertas; tinjauan menyebut atribut yang dilanggar tiap pengecoh. Lalu satu set berbatas waktu dua belas soal. Catat persentase figuralmu sebagai bagian profil garis dasar di Dossier.'),
  takeaways: take([['Name the family, then run the attribute table in a fixed order.', 'Sebutkan keluarganya, lalu jalankan tabel atribut dalam urutan tetap.'], ['Rotation keeps clockwise order; the mirror is the distractor.', 'Putaran menjaga urutan searah jarum jam; cermin adalah pengecohnya.'], ['Nets fold by the straight-run-of-three rule.', 'Jaring dilipat dengan aturan garis lurus tiga kotak.']]),
  resources: res('Practice notes', 'Catatan latihan', 'Where the figural families appear and what to verify.', 'Di mana keluarga figural muncul dan apa yang perlu diverifikasi.', [['Figural families by test', 'Keluarga figural per tes', 'Verify per programme; formats change.', 'Verifikasi per program; format berubah.', [['SKD TIU figural sub-topics: analogi, ketidaksamaan, serial (PermenPAN-RB blueprint; verify the current cycle). BUMN TKD and TPA batteries vary by provider and commonly add matrices and spatial items.', 'Sub-topik figural TIU SKD: analogi, ketidaksamaan, serial (kisi-kisi PermenPAN-RB; verifikasi siklus berjalan). TKD BUMN dan baterai TPA berbeda per penyedia dan umumnya menambahkan matriks dan soal spasial.'], [NOTICE.en, NOTICE.id]]]])
});

const L76 = lesson({
  n: '7.6', kind: 'reading', dur: dur(40),
  title: b('Classic Psikotes: Kraepelin, Pauli, IST-type, CFIT-type and Drawing Tasks', 'Psikotes Klasik: Kraepelin, Pauli, Tipe IST, Tipe CFIT, dan Tugas Menggambar'),
  overview: b('Many Indonesian employers still run a paper psikotes before or alongside online tests: a column-adding speed test, a battery of nine short sub-tests, a culture-fair matrices test and one or more drawing tasks. This lesson explains what each instrument is trying to measure and how it is scored, what honest preparation looks like, and what you cannot and should not try to game. Instrument names are given for orientation; the Lab reproduces no copyrighted items and offers its own simulator only where the task is generic.', 'Banyak perusahaan Indonesia masih menjalankan psikotes kertas sebelum atau bersamaan dengan tes daring: tes kecepatan menjumlah kolom, baterai sembilan sub-tes pendek, tes matriks bebas budaya, dan satu atau lebih tugas menggambar. Pelajaran ini menjelaskan apa yang coba diukur tiap instrumen dan cara penilaiannya, seperti apa persiapan yang jujur, dan apa yang tidak bisa dan tidak sepatutnya kamu akali. Nama instrumen disebut untuk orientasi; Lab tidak mereproduksi soal berhak cipta dan hanya menawarkan simulator buatan sendiri untuk tugas yang generik.'),
  objectives: [b('Explain what the Kraepelin and Pauli column tests score: speed, accuracy, consistency and the work curve.', 'Menjelaskan apa yang dinilai tes kolom Kraepelin dan Pauli: kecepatan, ketepatan, konsistensi, dan kurva kerja.'), b('Describe the structure of an IST-type battery and prepare for its generic sub-tests without proprietary items.', 'Menggambarkan struktur baterai tipe IST dan bersiap untuk sub-tes generiknya tanpa soal berhak cipta.'), b('Approach matrices tests with the figural method from Lesson 7.4.', 'Menghadapi tes matriks dengan metode figural dari Pelajaran 7.4.'), b('Treat drawing tasks honestly: what they are used for, and why “tips” to game them backfire.', 'Menyikapi tugas menggambar dengan jujur: untuk apa dipakai, dan mengapa “tips” mengakalinya justru merugikan.')],
  readFirst: rf('Four instruments, one honest stance', 'Empat instrumen, satu sikap jujur', 'What the paper psikotes measures and how to prepare without pretending.', 'Apa yang diukur psikotes kertas dan cara bersiap tanpa berpura-pura.', [
    ['Column tests measure rhythm', 'Tes kolom mengukur ritme', [['Kraepelin and Pauli score speed, accuracy and, above all, consistency across intervals.', 'Kraepelin dan Pauli menilai kecepatan, ketepatan, dan terutama konsistensi antar interval.'], ['A steady line beats a fast start that collapses.', 'Garis yang stabil mengalahkan awal yang cepat lalu runtuh.']]],
    ['Batteries are families you know', 'Baterai adalah keluarga yang sudah kamu kenal', [['IST-type batteries are verbal, numerical and figural sub-tests in short bursts.', 'Baterai tipe IST adalah sub-tes verbal, numerik, dan figural dalam durasi singkat.'], ['Prepare the families, not the instrument.', 'Siapkan keluarganya, bukan instrumennya.']]],
    ['Matrices are figural', 'Matriks adalah figural', [['Culture-fair matrices tests are the figural matrix family at speed.', 'Tes matriks bebas budaya adalah keluarga matriks figural dengan kecepatan.'], ['Row rule, column rule, cell that satisfies both.', 'Aturan baris, aturan kolom, sel yang memenuhi keduanya.']]],
    ['Drawing is not a trick', 'Menggambar bukan trik', [['Drawing tasks are projective and interpreted by a psychologist in context.', 'Tugas menggambar bersifat proyektif dan ditafsirkan psikolog dalam konteks.'], ['Draw honestly and completely; gaming advice is usually wrong and visible.', 'Gambar dengan jujur dan lengkap; saran mengakali biasanya keliru dan terlihat.']]]
  ]),
  sections: [
    sec('stopwatch', 'Kraepelin and Pauli: what the columns score', 'Kraepelin dan Pauli: apa yang dinilai kolom', 'Both tests ask you to add adjacent single digits in long columns, writing only the last digit of each sum, for a fixed time per column or per interval. Nobody finishes. Scoring reads four things from your sheet: <b>speed</b> (how many sums per interval), <b>accuracy</b> (errors and skipped pairs), <b>consistency</b> (how much speed varies from interval to interval), and the <b>work curve</b> (does output rise, hold, or collapse as fatigue sets in). The profile is compared with a norm, and the interpretation is about work habits: steadiness, endurance, care under monotony. Pauli is longer and signals the interval with a command to draw a line; Kraepelin moves column by column. Treat both as the same task.', 'Keduanya meminta kamu menjumlahkan dua angka satuan yang berdekatan dalam kolom panjang, menulis hanya angka terakhir dari tiap jumlah, selama waktu tetap per kolom atau per interval. Tidak ada yang selesai. Penilaian membaca empat hal dari lembarmu: <b>kecepatan</b> (berapa jumlah per interval), <b>ketepatan</b> (kesalahan dan pasangan yang terlewat), <b>konsistensi</b> (seberapa besar kecepatan berubah antar interval), dan <b>kurva kerja</b> (apakah hasil naik, bertahan, atau runtuh saat lelah datang). Profilnya dibandingkan dengan norma, dan tafsirannya menyangkut kebiasaan kerja: kestabilan, daya tahan, ketelitian dalam kemonotonan. Pauli lebih panjang dan menandai interval dengan aba-aba menarik garis; Kraepelin bergerak kolom demi kolom. Perlakukan keduanya sebagai tugas yang sama.'),
    sec('trendUp', 'The rhythm method', 'Metode ritme', 'Candidates lose on the column tests in one of two ways: sprinting the first intervals and collapsing, or stopping to check sums and leaving gaps. The fix is a <b>rhythm</b>: pick a pace you can hold for the whole test (in the Lab simulator you will find it in two sessions), start at that pace rather than above it, never go back to check, and never skip a pair. If you notice an error, leave it; one error costs less than the gap and the lost rhythm. Breathe on the interval signal. Practise with pencil and paper, not only on screen, because the real test is physical: a dull pencil and a cramped hand cost sums.', 'Peserta kalah pada tes kolom dengan satu dari dua cara: berlari kencang di interval awal lalu runtuh, atau berhenti memeriksa jumlah dan meninggalkan celah. Penyelesaiannya adalah <b>ritme</b>: pilih tempo yang bisa kamu pertahankan sepanjang tes (di simulator Lab kamu akan menemukannya dalam dua sesi), mulai pada tempo itu dan bukan di atasnya, jangan pernah kembali memeriksa, dan jangan pernah melewati pasangan. Jika sadar ada kesalahan, tinggalkan; satu kesalahan lebih murah daripada celah dan ritme yang hilang. Bernapaslah pada aba-aba interval. Berlatihlah dengan pensil dan kertas, bukan hanya di layar, karena tes sesungguhnya bersifat fisik: pensil tumpul dan tangan kram memakan jumlah.'),
    sec('layers', 'IST-type batteries: orientation only', 'Baterai tipe IST: orientasi saja', 'Some employers use a licensed intelligence battery of nine short sub-tests, each a few minutes: sentence completion, word exclusion, analogies, commonalities, arithmetic, number series, figure selection, cube rotation and memory. The items are proprietary and the Lab does not reproduce them. What you can and should prepare is the <b>families</b>: every sub-test is one of the verbal, numerical or figural families in Lessons 7.2 to 7.4, under a short clock. The memory sub-test is the only genuinely different one: you study a list of words grouped by category for a few minutes and then answer which category a word belonged to. Practise with any grouped list; the skill is the grouping, not the words.', 'Sebagian perusahaan memakai baterai inteligensi berlisensi dengan sembilan sub-tes pendek, masing-masing beberapa menit: melengkapi kalimat, mengeluarkan kata, analogi, persamaan, berhitung, deret angka, memilih gambar, memutar kubus, dan ingatan. Soalnya berhak cipta dan Lab tidak mereproduksinya. Yang bisa dan sebaiknya kamu siapkan adalah <b>keluarganya</b>: setiap sub-tes adalah salah satu keluarga verbal, numerik, atau figural dari Pelajaran 7.2 sampai 7.4, di bawah jam yang pendek. Sub-tes ingatan adalah satu-satunya yang benar-benar berbeda: kamu mempelajari daftar kata yang dikelompokkan per kategori selama beberapa menit lalu menjawab kata mana termasuk kategori mana. Berlatihlah dengan daftar berkelompok apa pun; keterampilannya adalah pengelompokan, bukan katanya.'),
    sec('grid', 'Matrices tests: CFIT-type and Raven-type', 'Tes matriks: tipe CFIT dan tipe Raven', 'Culture-fair tests avoid language and use figures: series, classification, matrices and conditions, or sixty matrices of rising difficulty. They are the figural family at speed. Use the method from Lesson 7.4: row rule, column rule, the cell that satisfies both; on harder matrices the rules combine (one shape per row <i>and</i> one shading per column <i>and</i> a count that adds across). The Lab’s own matrices are built on the same principles so the method transfers; the real items are proprietary and different.', 'Tes bebas budaya menghindari bahasa dan memakai gambar: deret, klasifikasi, matriks dan kondisi, atau enam puluh matriks dengan kesulitan meningkat. Semuanya adalah keluarga figural dengan kecepatan. Pakai metode dari Pelajaran 7.4: aturan baris, aturan kolom, sel yang memenuhi keduanya; pada matriks yang lebih sulit aturannya bergabung (satu bentuk per baris <i>dan</i> satu isi per kolom <i>dan</i> jumlah yang bertambah menyilang). Matriks buatan Lab dibangun pada prinsip yang sama sehingga metodenya berpindah; soal sesungguhnya berhak cipta dan berbeda.'),
    sec('pen', 'Drawing tasks: honest limits', 'Tugas menggambar: batas yang jujur', 'A person, a tree, and a sheet of eight boxes with small marks to complete into pictures are projective tasks: a psychologist reads them with your interview and the rest of the battery, never alone. The internet is full of “draw the tree with roots and fruit” advice; most of it is folklore, and a rehearsed drawing is often visible to a trained reader. Honest preparation is simple: draw completely (a whole person with hands and feet, a whole tree), use the time, write the title or story if asked, and do not leave boxes blank. Beyond that, be yourself; the task is not a puzzle with a key, and Metanoia will not pretend it has one.', 'Gambar orang, gambar pohon, dan selembar kertas berisi delapan kotak dengan tanda kecil untuk dilengkapi menjadi gambar adalah tugas proyektif: psikolog membacanya bersama wawancara dan baterai tes lainnya, tidak pernah sendirian. Internet penuh saran “gambar pohon dengan akar dan buah”; sebagian besar cerita rakyat, dan gambar yang dilatih sering terlihat oleh pembaca terlatih. Persiapan yang jujur sederhana: gambar dengan lengkap (orang utuh dengan tangan dan kaki, pohon utuh), pakai waktunya, tulis judul atau ceritanya bila diminta, dan jangan biarkan kotak kosong. Selebihnya, jadilah dirimu; tugas ini bukan teka-teki berkunci, dan Metanoia tidak akan berpura-pura memilikinya.'),
    sec('shieldTick', 'Names, rights and what the Lab does', 'Nama, hak, dan apa yang dilakukan Lab', 'Instrument names appear here so you recognise them on an invitation; naming them is orientation, not endorsement. The Lab provides a <b>Kraepelin-style simulator</b> (random digits, your own intervals, a work-curve graph) because column addition is a generic task; it provides matrices and figural items built on its own rules; it provides no IST-type items, no drawing “keys” and no reproduction of any published test. If an invitation names an instrument not covered here, ask the employer or provider for their practice page, which many publish.', 'Nama instrumen muncul di sini agar kamu mengenalinya di undangan; menyebutnya adalah orientasi, bukan dukungan. Lab menyediakan <b>simulator gaya Kraepelin</b> (angka acak, interval pilihanmu, grafik kurva kerja) karena menjumlah kolom adalah tugas generik; menyediakan matriks dan soal figural yang dibangun dengan aturan sendiri; tidak menyediakan soal tipe IST, “kunci” menggambar, maupun reproduksi tes terbitan mana pun. Jika undangan menyebut instrumen yang tidak dibahas di sini, mintalah laman latihan dari perusahaan atau penyedianya, yang banyak di antaranya dipublikasikan.')
  ],
  diagram: flow('Exhibit 1: Reading a column-test profile', 'Peraga 1: Membaca profil tes kolom', 'Four readings from one sheet, and what each one says about work habits', 'Empat bacaan dari satu lembar, dan apa kata masing-masing tentang kebiasaan kerja', [
    ['zap', 'Speed', 'Kecepatan', 'Sums per interval; compared with a norm, not with your friends.', 'Jumlah per interval; dibandingkan dengan norma, bukan dengan temanmu.'],
    ['target', 'Accuracy', 'Ketepatan', 'Errors and skipped pairs; a few are normal, gaps are not.', 'Kesalahan dan pasangan terlewat; sedikit itu wajar, celah tidak.'],
    ['balance', 'Consistency', 'Konsistensi', 'Spread between your best and worst intervals; small is good.', 'Rentang antara interval terbaik dan terburukmu; kecil itu baik.'],
    ['trendUp', 'Work curve', 'Kurva kerja', 'Rising, flat or collapsing output over time; the shape is the story.', 'Hasil naik, datar, atau runtuh seiring waktu; bentuknya adalah ceritanya.']
  ]),
  compare: [cmp('Two first intervals', 'Dua interval pertama', 'The Kraepelin sheet lands; thirty seconds per column.', 'Lembar Kraepelin tiba; tiga puluh detik per kolom.', 'Races the first column, twenty-two sums, thrilled. Column four: fourteen. Column nine: nine, two gaps, hand cramping. Profile: fast start, steep collapse, erratic.', 'Berlari di kolom pertama, dua puluh dua jumlah, girang. Kolom empat: empat belas. Kolom sembilan: sembilan, dua celah, tangan kram. Profil: awal cepat, runtuh tajam, tidak menentu.', 'Starts at the pace found in the simulator, sixteen a column, and holds it. Column nine: fifteen. No gaps. Profile: steady, enduring, careful.', 'Mulai pada tempo yang ditemukan di simulator, enam belas per kolom, dan mempertahankannya. Kolom sembilan: lima belas. Tanpa celah. Profil: stabil, tahan lama, teliti.', 'Total sums are similar; the second profile is what the test is built to find.', 'Total jumlahnya mirip; profil kedua adalah yang dirancang untuk ditemukan tes ini.')],
  scenario: scen('stopwatch', 'In focus: the pencil', 'Sorotan: pensil', [['A candidate who had practised the simulator on her phone sat the paper Kraepelin with a soft 2B pencil that smudged; by column twelve her digits were unreadable to her own eye and she began rewriting them. Her consistency score collapsed from the rewriting, not the adding.', 'Seorang kandidat yang berlatih simulator di ponselnya mengerjakan Kraepelin kertas dengan pensil 2B lunak yang luntur; pada kolom dua belas angkanya tidak terbaca oleh matanya sendiri dan ia mulai menulis ulang. Skor konsistensinya runtuh karena penulisan ulang, bukan penjumlahan.'], ['Classic psikotes is physical. Practise once with the pencil and paper you will use, and sharpen two.', 'Psikotes klasik bersifat fisik. Berlatihlah sekali dengan pensil dan kertas yang akan dipakai, dan raut dua pensil.']]),
  steps: [
    step('Drill 1 · Find your pace', 'Latihan 1 · Temukan tempomu', 'Run the Lab’s Kraepelin simulator twice at thirty-second intervals, twenty intervals. First run: as fast as you can. Second run: at 85% of the first run’s best interval, held steady.', 'Jalankan simulator Kraepelin di Lab dua kali dengan interval tiga puluh detik, dua puluh interval. Lari pertama: secepat mungkin. Lari kedua: pada 85% dari interval terbaik lari pertama, dipertahankan stabil.', 'Compare the two work curves. The second will have a smaller spread and, usually, a higher total. That pace is your rhythm; write it in the Dossier.', 'Bandingkan kedua kurva kerja. Yang kedua akan memiliki rentang lebih kecil dan, biasanya, total lebih tinggi. Tempo itu adalah ritmemu; tulis di Dossier.'),
    step('Drill 2 · Paper transfer', 'Latihan 2 · Pindah ke kertas', 'Print or hand-write six columns of random digits and run the same rhythm with a pencil for six intervals. Count sums, errors and gaps yourself.', 'Cetak atau tulis tangan enam kolom angka acak dan jalankan ritme yang sama dengan pensil selama enam interval. Hitung sendiri jumlah, kesalahan, dan celah.', 'If paper output is more than 20% below screen output, the gap is physical: pencil, grip, posture. Fix those before adding speed.', 'Jika hasil di kertas lebih dari 20% di bawah hasil di layar, celahnya fisik: pensil, genggaman, postur. Perbaiki itu sebelum menambah kecepatan.'),
    step('Drill 3 · Grouped-list memory', 'Latihan 3 · Ingatan daftar berkelompok', 'Write five categories with five words each (flowers, tools, cities, animals, professions). Study for three minutes, cover, and answer twenty questions of the form “which category was X in?”.', 'Tulis lima kategori dengan lima kata masing-masing (bunga, alat, kota, hewan, profesi). Pelajari tiga menit, tutup, dan jawab dua puluh pertanyaan berbentuk “X termasuk kategori mana?”.', 'Group by the first letter inside each category and build one image per category. The second attempt is usually near-perfect; the skill is the encoding, not the memory.', 'Kelompokkan berdasarkan huruf pertama di dalam tiap kategori dan bangun satu gambaran per kategori. Percobaan kedua biasanya hampir sempurna; keterampilannya adalah pengodean, bukan ingatan.')
  ],
  mistakes: mist([['Sprinting the first column', 'Berlari di kolom pertama', 'Start at your rhythm; the test rewards the shape of the curve.', 'Mulai pada ritmemu; tes menghargai bentuk kurva.'], ['Going back to check a sum', 'Kembali memeriksa jumlah', 'Never; an error is cheaper than a gap and a broken rhythm.', 'Jangan pernah; kesalahan lebih murah daripada celah dan ritme yang rusak.'], ['Memorising “tips” for drawing tasks', 'Menghafal “tips” untuk tugas menggambar', 'Draw completely and honestly; rehearsed drawings are visible.', 'Gambar dengan lengkap dan jujur; gambar yang dilatih terlihat.'], ['Hunting for leaked IST items', 'Memburu bocoran soal IST', 'Illegal, often wrong, and unnecessary: prepare the families.', 'Melanggar hukum, sering keliru, dan tidak perlu: siapkan keluarganya.']]),
  glossary: gl([['Kraepelin test', 'Tes Kraepelin', 'Column addition of adjacent digits under time; scores speed, accuracy, consistency, work curve.', 'Penjumlahan kolom angka berdekatan dalam batas waktu; menilai kecepatan, ketepatan, konsistensi, kurva kerja.'], ['Pauli test', 'Tes Pauli', 'A longer column-addition test with interval signals; interpreted the same way.', 'Tes penjumlahan kolom yang lebih panjang dengan aba-aba interval; ditafsirkan dengan cara yang sama.'], ['Work curve', 'Kurva kerja', 'Output per interval plotted over time.', 'Hasil per interval yang digambarkan terhadap waktu.'], ['IST-type battery', 'Baterai tipe IST', 'A licensed nine-sub-test intelligence battery; proprietary items.', 'Baterai inteligensi berlisensi sembilan sub-tes; soal berhak cipta.'], ['Culture-fair test', 'Tes bebas budaya', 'Figural tests designed to avoid language and schooling effects.', 'Tes figural yang dirancang menghindari pengaruh bahasa dan sekolah.'], ['Projective task', 'Tugas proyektif', 'A drawing or completion task interpreted by a psychologist in context.', 'Tugas menggambar atau melengkapi yang ditafsirkan psikolog dalam konteks.']]),
  checks: [
    chk('On a column-addition test, noticing an error two rows back, you should …', 'Pada tes penjumlahan kolom, saat menyadari kesalahan dua baris sebelumnya, kamu sebaiknya …', [['go back and correct it', 'kembali dan memperbaikinya'], ['leave it and keep the rhythm', 'membiarkannya dan menjaga ritme'], ['skip the next pair to catch up', 'melewati pasangan berikutnya untuk mengejar'], ['stop until the next interval', 'berhenti sampai interval berikutnya']], 1, 'One error costs less than a gap plus a broken rhythm; consistency is scored.', 'Satu kesalahan lebih murah daripada celah plus ritme yang rusak; konsistensi dinilai.'),
    chk('The honest way to prepare for an IST-type battery is …', 'Cara jujur bersiap menghadapi baterai tipe IST adalah …', [['to find the real items online', 'mencari soal aslinya di internet'], ['to prepare the verbal, numerical and figural families under a short clock, plus grouped-list memory', 'menyiapkan keluarga verbal, numerik, dan figural di bawah jam pendek, plus ingatan daftar berkelompok'], ['to memorise the drawing “keys”', 'menghafal “kunci” menggambar'], ['to skip it; it cannot be prepared', 'melewatkannya; tidak bisa disiapkan']], 1, 'Items are proprietary; the families and the memory skill are generic and trainable.', 'Soalnya berhak cipta; keluarganya dan keterampilan ingatannya generik dan bisa dilatih.'),
    chk('Drawing tasks in a psikotes are …', 'Tugas menggambar dalam psikotes adalah …', [['puzzles with a published answer key', 'teka-teki dengan kunci jawaban terbitan'], ['projective tasks read by a psychologist together with the rest of the battery', 'tugas proyektif yang dibaca psikolog bersama baterai lainnya'], ['tests of artistic ability', 'tes kemampuan seni'], ['optional and never scored', 'opsional dan tidak pernah dinilai']], 1, 'No key exists; draw completely and honestly.', 'Tidak ada kunci; gambar dengan lengkap dan jujur.')
  ],
  tool: tool('kraepelin', 'The Kraepelin-style simulator', 'Simulator gaya Kraepelin', 'Random single digits in columns, your interval length (default 30 seconds) and count (default 20), a work-curve graph per interval with consistency and slope. Run it twice as Drill 1 describes and record your rhythm in the Dossier. It is Metanoia’s own generic simulator, not a reproduction of any published test form.', 'Angka satuan acak dalam kolom, panjang interval pilihanmu (bawaan 30 detik) dan jumlahnya (bawaan 20), grafik kurva kerja per interval dengan konsistensi dan kemiringan. Jalankan dua kali seperti Latihan 1 dan catat ritmemu di Dossier. Ini simulator generik milik Metanoia, bukan reproduksi formulir tes terbitan mana pun.', 'Open the simulator →', 'Buka simulator →'),
  takeaways: take([['Column tests score the shape of your work curve; find and hold a rhythm.', 'Tes kolom menilai bentuk kurva kerjamu; temukan dan pertahankan ritme.'], ['Batteries and matrices tests are the families you already train; prepare those, not leaked items.', 'Baterai dan tes matriks adalah keluarga yang sudah kamu latih; siapkan itu, bukan bocoran soal.'], ['Drawing tasks have no key; draw completely and be yourself.', 'Tugas menggambar tidak punya kunci; gambar lengkap dan jadilah dirimu.']]),
  resources: res('Orientation notes', 'Catatan orientasi', 'What to verify before a classic psikotes.', 'Apa yang perlu diverifikasi sebelum psikotes klasik.', [['Before the day', 'Sebelum harinya', 'Ask the employer or provider.', 'Tanyakan kepada perusahaan atau penyedia.', [['Which instruments, paper or screen, how long, whether a calculator or scrap paper is allowed, and whether the provider publishes a practice page. Verify rights before relying on any third-party “original items”; licensed instruments are not legally reproducible.', 'Instrumen apa, kertas atau layar, berapa lama, apakah kalkulator atau kertas coret diizinkan, dan apakah penyedia memublikasikan laman latihan. Verifikasi hak sebelum mengandalkan “soal asli” pihak ketiga; instrumen berlisensi tidak boleh direproduksi secara hukum.'], ['Instrument names are given for orientation; we reproduce no copyrighted items.', 'Nama instrumen disebut untuk orientasi; kami tidak mereproduksi soal berhak cipta.']]]])
});

/* additions to existing lessons, keyed by their NEW numbers */
const PATCH = {
  '7.1': {
    sections: [sec('compass', 'Which track? A two-minute router', 'Jalur mana? Pemandu dua menit', 'Three employer types, three test regimes. <b>Private sector</b> (banks, FMCG, consulting, tech): online aptitude batteries, sometimes a paper psikotes; prepare the families in this module. <b>BUMN</b> (state-owned enterprises, joint recruitment): a TKD of the same families plus an AKHLAK values test, English and learning agility; Module 12 Track B. <b>PNS/CPNS</b>: the SKD, a 110-item computer-assisted test with TWK (national insight), TIU (general intelligence) and TKP (personal characteristics) scored against published thresholds; Module 12 Track C. All three share the numerical, verbal and figural core, so finish Module 7 first, then take the Lab diagnostic and let the recommendation choose your Module 12 track.', 'Tiga jenis pemberi kerja, tiga rezim tes. <b>Sektor swasta</b> (bank, FMCG, konsultan, teknologi): baterai tes bakat daring, kadang psikotes kertas; siapkan keluarga-keluarga di modul ini. <b>BUMN</b> (rekrutmen bersama): TKD dengan keluarga yang sama plus tes nilai AKHLAK, bahasa Inggris, dan learning agility; Modul 12 Jalur B. <b>PNS/CPNS</b>: SKD, tes berbantuan komputer 110 soal dengan TWK (wawasan kebangsaan), TIU (intelegensia umum), dan TKP (karakteristik pribadi) yang dinilai terhadap ambang batas terbitan; Modul 12 Jalur C. Ketiganya berbagi inti numerik, verbal, dan figural, jadi selesaikan Modul 7 dulu, lalu ambil diagnostik Lab dan biarkan rekomendasinya memilih jalur Modul 12-mu.')],
    compare: [cmp('Three invitations, one core', 'Tiga undangan, satu inti', 'Nadia holds a bank officer-programme invitation; her cousin a BUMN joint-recruitment registration; her neighbour a CPNS formation.', 'Nadia memegang undangan ODP bank; sepupunya pendaftaran rekrutmen bersama BUMN; tetangganya formasi CPNS.', 'Each buys a different “bank soal” book and starts on page one. Three weeks later none has a baseline and all three have practised the same numerical traps twice over.', 'Masing-masing membeli buku “bank soal” berbeda dan mulai dari halaman satu. Tiga minggu kemudian tak satu pun punya garis dasar dan ketiganya melatih jebakan numerik yang sama dua kali.', 'All three take the Lab’s 40-item mixed diagnostic. The weakness map shows the same two red sub-types for each. They drill those in Module 7, then split: 12.1 to 12.6, 12.7 to 12.10, 12.11 to 12.18.', 'Ketiganya mengambil diagnostik campuran 40 soal di Lab. Peta kelemahan menunjukkan dua sub-tipe merah yang sama untuk masing-masing. Mereka melatihnya di Modul 7, lalu berpisah: 12.1 sampai 12.6, 12.7 sampai 12.10, 12.11 sampai 12.18.', 'The core is shared; the format layer is not. Diagnose first, then choose the track.', 'Intinya sama; lapisan formatnya tidak. Diagnosis dulu, lalu pilih jalur.')],
    tool: tool('diagnostic:mixed40', 'Your baseline: the 40-item mixed diagnostic', 'Garis dasarmu: diagnostik campuran 40 soal', 'Before any technique, sit the Lab’s untimed mixed diagnostic: ten numerical, ten verbal, ten reasoning, ten figural, all original Metanoia items. The weakness map that follows is Dossier item 1 for this module and the input to the Module 12 track recommendation. The Lab reports against its own bank, not any employer’s cut-off; the shape of the profile decides where the three weeks go.', 'Sebelum teknik apa pun, kerjakan diagnostik campuran tanpa batas waktu di Lab: sepuluh numerik, sepuluh verbal, sepuluh penalaran, sepuluh figural, semuanya soal asli Metanoia. Peta kelemahan yang mengikutinya adalah butir Dossier 1 untuk modul ini dan masukan bagi rekomendasi jalur Modul 12. Lab melaporkan terhadap bank soalnya sendiri, bukan ambang perusahaan mana pun; bentuk profil menentukan ke mana tiga minggu itu diarahkan.')
  },
  '7.2': {
    steps: [step('Drill 6 · P versus Q', 'Latihan 6 · P versus Q', 'Quantitative comparison: two quantities, four fixed options (P greater, Q greater, equal, cannot be determined). Eight items in the Lab. Rule: whenever a variable appears, test a fraction between 0 and 1 and a negative before you answer.', 'Perbandingan kuantitatif: dua besaran, empat opsi tetap (P lebih besar, Q lebih besar, sama, tidak dapat ditentukan). Delapan soal di Lab. Aturan: setiap kali ada variabel, uji pecahan antara 0 dan 1 dan bilangan negatif sebelum menjawab.', 'Most misses come from testing one friendly integer. “Cannot be determined” is right exactly when two test values give different orders.', 'Kebanyakan kesalahan berasal dari menguji satu bilangan bulat yang ramah. “Tidak dapat ditentukan” benar tepat ketika dua nilai uji memberi urutan berbeda.'), step('Drill 7 · Letter series with EJOTY', 'Latihan 7 · Deret huruf dengan EJOTY', 'Write E5 J10 O15 T20 Y25 at the top of your scrap paper. Convert each letter to its number, solve as a number series, convert back. Eight items in the Lab.', 'Tulis E5 J10 O15 T20 Y25 di bagian atas kertas coretmu. Ubah tiap huruf ke angkanya, selesaikan sebagai deret angka, ubah kembali. Delapan soal di Lab.', 'The anchors cut conversion time by half; wrap past Z back to A. Two-lane letter series are the same as two-lane number series.', 'Jangkar memangkas waktu konversi setengahnya; putar melewati Z kembali ke A. Deret huruf dua larik sama dengan deret angka dua larik.')],
    tool: tool('drill:numerik', 'Numerical drills in the Test Lab', 'Latihan numerik di Test Lab', 'Six tiered sub-types: arithmetic, number series, letter series, P versus Q, story problems and table reading. Untimed first with instant structured feedback (key, pattern, steps, trap, shortcut); tag every miss; then timed sets. The weakness map decides next week.', 'Enam sub-tipe bertingkat: aritmetika, deret angka, deret huruf, P versus Q, soal cerita, dan membaca tabel. Tanpa batas waktu dulu dengan umpan balik terstruktur seketika (kunci, pola, langkah, jebakan, cara cepat); tandai tiap kesalahan; lalu set berbatas waktu. Peta kelemahan menentukan minggu depan.')
  },
  '7.3': {
    sections: [sec('scale', 'Syllogism rules in one table', 'Aturan silogisme dalam satu tabel', 'Four valid shapes cover the exam: <b>all A are B, all B are C → all A are C</b>; <b>no A is B, all C are A → no C is B</b>; <b>all A are B, some C are A → some C are B</b>; <b>no A is B, some C are A → some C are not B</b>. Three signals mean “no valid conclusion”: two negative premises, two particular (“some”) premises, or a middle term that is never “all/no” (the undistributed middle: all A are B, all C are B). The negation table: not “all A are B” is “some A are not B”; not “some A are B” is “no A is B”; not “if p then q” is “p and not q”; not “p and q” is “not p or not q”.', 'Empat bentuk sah mencakup ujian: <b>semua A adalah B, semua B adalah C → semua A adalah C</b>; <b>tidak ada A yang B, semua C adalah A → tidak ada C yang B</b>; <b>semua A adalah B, sebagian C adalah A → sebagian C adalah B</b>; <b>tidak ada A yang B, sebagian C adalah A → sebagian C bukan B</b>. Tiga tanda berarti “tidak ada kesimpulan sah”: dua premis negatif, dua premis partikular (“sebagian”), atau suku tengah yang tidak pernah “semua/tidak ada” (suku tengah tak tersebar: semua A adalah B, semua C adalah B). Tabel ingkaran: ingkaran “semua A adalah B” adalah “sebagian A bukan B”; ingkaran “sebagian A adalah B” adalah “tidak ada A yang B”; ingkaran “jika p maka q” adalah “p dan tidak q”; ingkaran “p dan q” adalah “tidak p atau tidak q”.'), sec('puzzle', 'Analytic games: introduction, constraints, questions', 'Permainan analitis: pengantar, pembatas, soal', 'An analytic set has three parts: an <b>introduction</b> (five people, four days, six candidates and three places), <b>constraints</b> (X is right after Y; P is not on Monday; if H then J) and three to five <b>questions</b>. Never answer from the first arrangement you find. Draw the frame, place the fixed constraint first, then the blocks (“right after”), then the conditionals, and write out <i>every</i> legal arrangement; most exam sets have two to four. “Must be true” is what holds in all of them; “could be true” is what holds in at least one; “if … then” questions pick one arrangement and read it off. The frame on scrap paper is the whole method.', 'Set analitis punya tiga bagian: <b>pengantar</b> (lima orang, empat hari, enam calon dan tiga kursi), <b>pembatas</b> (X tepat setelah Y; P bukan Senin; jika H maka J), dan tiga sampai lima <b>soal</b>. Jangan pernah menjawab dari susunan pertama yang ditemukan. Gambar kerangkanya, tempatkan pembatas tetap dulu, lalu blok (“tepat setelah”), lalu syarat bersyarat, dan tulis <i>setiap</i> susunan sah; kebanyakan set ujian punya dua sampai empat. “Pasti benar” adalah yang berlaku di semuanya; “mungkin benar” yang berlaku di setidaknya satu; soal “jika … maka” memilih satu susunan dan membacanya. Kerangka di kertas coret adalah seluruh metodenya.')],
    steps: [step('Drill 5 · Syllogism table', 'Latihan 5 · Tabel silogisme', 'Ten syllogism and conditional items in the Lab. Before answering, write the shape (AAA, EAE, AII, EIO, or one of the three “no conclusion” signals).', 'Sepuluh soal silogisme dan kondisional di Lab. Sebelum menjawab, tulis bentuknya (AAA, EAE, AII, EIO, atau salah satu dari tiga tanda “tidak ada kesimpulan”).', 'Items keyed “no valid conclusion” are where most marks are lost; the shape tells you before the content tempts you.', 'Soal berkunci “tidak ada kesimpulan sah” adalah tempat kebanyakan nilai hilang; bentuknya memberi tahu sebelum isinya menggoda.'), step('Drill 6 · One analytic set, all arrangements', 'Latihan 6 · Satu set analitis, semua susunan', 'Take one analytic set in the Lab. Write every legal arrangement before opening the first question; then answer all three from the list.', 'Ambil satu set analitis di Lab. Tulis setiap susunan sah sebelum membuka soal pertama; lalu jawab ketiganya dari daftar itu.', 'The first question in a set costs ninety seconds; the next two cost twenty each, because the list already exists. That is the pacing argument for the method.', 'Soal pertama dalam satu set memakan sembilan puluh detik; dua berikutnya dua puluh detik masing-masing, karena daftarnya sudah ada. Itulah argumen tempo untuk metode ini.')],
    tool: tool('drill:penalaran', 'Verbal and reasoning drills in the Test Lab', 'Latihan verbal dan penalaran di Test Lab', 'Synonyms, antonyms, analogies and passages; syllogisms, conditionals, negations and analytic sets. Untimed with structured feedback first, then timed. “Cannot say chosen as true” and “no conclusion missed” get their own trap tags in the error log.', 'Sinonim, antonim, analogi, dan wacana; silogisme, kondisional, ingkaran, dan set analitis. Tanpa batas waktu dengan umpan balik terstruktur dulu, lalu berbatas waktu. “Tidak bisa disimpulkan dipilih sebagai benar” dan “tidak ada kesimpulan terlewat” punya tanda jebakan sendiri di catatan kesalahan.')
  },
  '7.5': {
    sections: [sec('heart', 'AKHLAK and BerAKHLAK side by side', 'AKHLAK dan BerAKHLAK berdampingan', 'Two keyed values frameworks matter in Indonesia. <b>AKHLAK</b> is the core values of state-owned enterprises (Kementerian BUMN, 2020): Amanah (trustworthy), Kompeten (competent), Harmonis (harmonious), Loyal, Adaptif (adaptive), Kolaboratif (collaborative). <b>BerAKHLAK</b> is the civil-service version (SE MenPAN-RB 20/2021): Berorientasi Pelayanan (service-oriented) in front, then the same six with Amanah replaced by Akuntabel (accountable). A values test for either asks you to rank or rate responses to scenarios; the keyed “best” response is the one that enacts the named value most completely while staying within your authority and the rules. The traps are the same in both: the heroic answer outside your authority, the loyal-to-a-person answer, and the second-best answer that helps but does not fix. Module 12 practises AKHLAK scenarios (12.8) and TKP dimensions (12.16 to 12.17) with ranked scoring.', 'Dua kerangka nilai berkunci penting di Indonesia. <b>AKHLAK</b> adalah nilai inti BUMN (Kementerian BUMN, 2020): Amanah, Kompeten, Harmonis, Loyal, Adaptif, Kolaboratif. <b>BerAKHLAK</b> adalah versi ASN (SE MenPAN-RB 20/2021): Berorientasi Pelayanan di depan, lalu enam yang sama dengan Amanah diganti Akuntabel. Tes nilai untuk keduanya meminta kamu mengurutkan atau menilai respons terhadap skenario; respons “terbaik” berkunci adalah yang menjalankan nilai yang disebut secara paling utuh sambil tetap dalam kewenangan dan aturan. Jebakannya sama di keduanya: jawaban heroik di luar kewenangan, jawaban setia-pada-orang, dan jawaban terbaik-kedua yang membantu tetapi tidak menyelesaikan. Modul 12 melatih skenario AKHLAK (12.8) dan dimensi TKP (12.16 sampai 12.17) dengan skor berjenjang.')],
    tool: tool('mirror', 'Consistency mirror and SJT calibration', 'Cermin konsistensi dan kalibrasi SJT', 'The Lab’s consistency mirror asks six value statements in two framings and shows where your answers disagree with each other; the AKHLAK and TKP drills score ranked options against Metanoia’s reasoning key with the ladder explained. Record in the Dossier your two top traits with one STAR story each, and any ranking where you disagree with the key and why.', 'Cermin konsistensi Lab menanyakan enam pernyataan nilai dalam dua bingkai dan menunjukkan di mana jawabanmu saling bertentangan; latihan AKHLAK dan TKP menilai opsi berjenjang terhadap kunci penalaran Metanoia dengan tangganya dijelaskan. Catat di Dossier dua sifat teratasmu dengan satu cerita STAR masing-masing, dan urutan mana pun yang kamu tidak sepakat dengan kunci beserta alasannya.')
  },
  '7.7': {
    sections: [sec('clock', 'Pacing a 110-item CAT', 'Mengatur tempo CAT 110 soal', 'The SKD gives 100 minutes for 110 items: about 55 seconds each if spread evenly, which is the wrong way to spread it. TWK items (30) are recall or application and should take 35 to 45 seconds; TKP items (45) are reading and judgement at about 50 seconds; that leaves roughly 72 seconds for each of the 35 TIU items, where the computation lives. Set three checkpoints on the on-screen clock (after TWK, after TIU, with 35 minutes left for TKP), answer every item because blanks score zero and there is no penalty, and use the flag (“Ragu-ragu”) for anything over 1.5× its budget. The Lab’s SKD-110 simulation enforces exactly this: a global timer, a question grid, flags and auto-submit, with a report against the configured thresholds. The simulation is a Metanoia form in an SKD-like format, not an imitation of any institution’s interface.', 'SKD memberi 100 menit untuk 110 soal: sekitar 55 detik per soal jika dibagi rata, dan itu cara membagi yang salah. Soal TWK (30) bersifat ingatan atau penerapan dan sebaiknya 35 sampai 45 detik; soal TKP (45) adalah membaca dan menimbang sekitar 50 detik; itu menyisakan kira-kira 72 detik untuk tiap dari 35 soal TIU, tempat perhitungan berada. Pasang tiga titik periksa pada jam di layar (setelah TWK, setelah TIU, dengan 35 menit tersisa untuk TKP), jawab setiap soal karena kosong bernilai nol dan tidak ada penalti, dan pakai tanda (“Ragu-ragu”) untuk soal apa pun yang melewati 1,5× anggarannya. Simulasi SKD-110 di Lab memberlakukan persis ini: pengatur waktu global, kisi soal, tanda, dan kirim otomatis, dengan laporan terhadap ambang batas yang dikonfigurasi. Simulasinya adalah formulir Metanoia dalam format mirip SKD, bukan tiruan antarmuka lembaga mana pun.')],
    compare: [cmp('Guessing by scoring rule, two more rows', 'Menebak berdasarkan aturan penilaian, dua baris lagi', 'The same decision, two Indonesian formats.', 'Keputusan yang sama, dua format Indonesia.', 'SKD CPNS: TWK and TIU score 5 for right and 0 for wrong or blank; TKP scores 1 to 5 per option and 0 for blank. Leaves eleven items blank “to be safe”. Loses up to 55 points on TWK/TIU and at least 11 on TKP for nothing.', 'SKD CPNS: TWK dan TIU bernilai 5 untuk benar dan 0 untuk salah atau kosong; TKP bernilai 1 sampai 5 per opsi dan 0 untuk kosong. Membiarkan sebelas soal kosong “biar aman”. Kehilangan sampai 55 poin di TWK/TIU dan setidaknya 11 di TKP tanpa alasan.', 'Answers everything: a blank can only score zero. On TKP, even the worst option scores 1. BUMN TKD: checks the invitation for a wrong-answer penalty; if none is stated (verify each cycle), answers everything too.', 'Menjawab semuanya: kosong hanya bisa bernilai nol. Di TKP, opsi terburuk pun bernilai 1. TKD BUMN: memeriksa undangan untuk penalti jawaban salah; jika tidak disebut (verifikasi tiap siklus), menjawab semuanya juga.', 'The guessing rule is a property of the scoring rule, read from the config panel, never from habit.', 'Aturan menebak adalah sifat dari aturan penilaian, dibaca dari panel konfigurasi, bukan dari kebiasaan.')],
    tool: tool('plan', 'Timed sets, the error log and the plan tracker', 'Set berbatas waktu, catatan kesalahan, dan pelacak rencana', 'From this week every Lab set is timed and every miss is tagged. Write your three-week plan in the plan tracker: six sessions a week, the family per session, the mocks in week 3. The error log, the weakness map and the plan are Dossier items 2 to 4 for this module. Add the test-day checklist for your nearest test.', 'Mulai minggu ini setiap set Lab berbatas waktu dan setiap kesalahan ditandai. Tulis rencana tiga minggumu di pelacak rencana: enam sesi seminggu, keluarga per sesi, simulasi di minggu 3. Catatan kesalahan, peta kelemahan, dan rencana adalah butir Dossier 2 sampai 4 untuk modul ini. Tambahkan daftar periksa hari tes untuk tes terdekatmu.')
  },
  '7.8': {
    tool: tool('diagnostic:mixed40', 'Week 1 starts now', 'Minggu 1 mulai sekarang', 'Your baseline from Step 6 is Dossier item 1. Run the six week-1 sessions in the Lab, untimed, tagging every miss; on Sunday, the weakness map’s two reddest sub-types choose week 2. In Step 7 you chose Nadia’s Module 12 track; the Lab’s recommendation screen now suggests yours, with a one-line reason.', 'Garis dasarmu dari Langkah 6 adalah butir Dossier 1. Jalankan enam sesi minggu 1 di Lab, tanpa batas waktu, tandai setiap kesalahan; pada Minggu, dua sub-tipe paling merah di peta kelemahan memilih minggu 2. Di Langkah 7 kamu memilih jalur Modul 12 Nadia; layar rekomendasi Lab kini menyarankan jalurmu, dengan alasan satu baris.'),
    caseStep: { title: b('Choose Nadia’s Module 12 track', 'Pilih jalur Modul 12 untuk Nadia'), short: b('Track', 'Jalur'), guide: b('Lesson 7.1 router. Nadia’s invitation is from a state-owned railway operator through the joint-recruitment portal, and her baseline is weakest in numerical. Which Module 12 track fits, which lessons first, and what does the track add that Module 7 does not cover?', 'Pemandu Pelajaran 7.1. Undangan Nadia berasal dari operator kereta api milik negara lewat portal rekrutmen bersama, dan garis dasarnya paling lemah di numerik. Jalur Modul 12 mana yang cocok, pelajaran mana lebih dulu, dan apa yang ditambahkan jalur itu yang tidak dicakup Modul 7?'), questions: [{ id: 'q7', min: 50, rows: 5, title: b('The track and the first three lessons', 'Jalur dan tiga pelajaran pertama'), help: b('Name the track (A, B or C) with the reason from the invitation; name the first three Module 12 lessons she should open after her Module 7 drills; name the one component of that track that Module 7 never trains.', 'Sebutkan jalurnya (A, B, atau C) dengan alasan dari undangan; sebutkan tiga pelajaran Modul 12 pertama yang harus ia buka setelah latihan Modul 7-nya; sebutkan satu komponen jalur itu yang tidak pernah dilatih Modul 7.'), placeholder: b('Track B, because the joint-recruitment portal means a TKD plus an AKHLAK values test … First 12.7 for the stages and the TKD format, then 12.8 because … The component Module 7 never trains is …', 'Jalur B, karena portal rekrutmen bersama berarti TKD plus tes nilai AKHLAK … Pertama 12.7 untuk tahapan dan format TKD, lalu 12.8 karena … Komponen yang tidak pernah dilatih Modul 7 adalah …') }] },
    caseModel: [{ h: b('The track', 'Jalur') }, b('Track B. The invitation came through the state-owned-enterprise joint-recruitment portal, so the regime is a TKD of the shared families plus the AKHLAK values test, English and a learning-agility instrument. Lessons 12.7 (stages and TKD format, with the timed 40-item set) and 12.8 (AKHLAK, ranked scoring) come first, because the values test is the component Module 7 only introduces and never drills with ranked scoring; 12.9 (English) follows, since her baseline says nothing about English yet. 12.10, the BUMN-T1 mock, waits for week 3.', 'Jalur B. Undangan datang lewat portal rekrutmen bersama BUMN, sehingga rezimnya adalah TKD dari keluarga bersama plus tes nilai AKHLAK, bahasa Inggris, dan instrumen learning agility. Pelajaran 12.7 (tahapan dan format TKD, dengan set berbatas waktu 40 soal) dan 12.8 (AKHLAK, skor berjenjang) lebih dulu, karena tes nilai adalah komponen yang hanya diperkenalkan Modul 7 dan tidak pernah dilatih dengan skor berjenjang; 12.9 (bahasa Inggris) menyusul, karena garis dasarnya belum berkata apa pun tentang bahasa Inggris. 12.10, simulasi BUMN-T1, menunggu minggu 3.')],
    journeyNext: { label: b('Module 12 · Recruitment Test Lab', 'Modul 12 · Recruitment Test Lab'), desc: b('Also available: the TPA, BUMN and SKD CPNS tracks, with the Lab’s mocks and the SKD-110 simulation. Then Module 8.', 'Juga tersedia: jalur TPA, BUMN, dan SKD CPNS, dengan simulasi Lab dan simulasi SKD-110. Lalu Modul 8.'), lesson: '12.1' }
  }
};

const MODULE = {
  overview: b('Online tests are the gate between the paper and the people for almost every high-volume graduate programme, and the most trainable gate in the funnel. Eight lessons and one case: the landscape and a track router, numerical, verbal and reasoning, figural and spatial, personality and values, the classic paper psikotes, strategy and pacing for fixed and computer-assisted tests, and Nadia’s three weeks. Every lesson drills in the Test Lab on original Metanoia items with structured feedback, an error log and a weakness map; Module 12 adds the BUMN and CPNS tracks.', 'Tes daring adalah gerbang antara kertas dan manusia untuk hampir setiap program lulusan bervolume tinggi, dan gerbang yang paling bisa dilatih di corong. Delapan pelajaran dan satu kasus: peta tes dan pemandu jalur, numerik, verbal dan penalaran, figural dan spasial, kepribadian dan nilai, psikotes kertas klasik, strategi dan tempo untuk tes tetap dan berbantuan komputer, dan tiga minggu Nadia. Setiap pelajaran berlatih di Test Lab pada soal asli Metanoia dengan umpan balik terstruktur, catatan kesalahan, dan peta kelemahan; Modul 12 menambahkan jalur BUMN dan CPNS.'),
  outcome: b('By the end of this module you can identify the tests a given programme is likely to use and route yourself to the right track; solve numerical, verbal, reasoning, figural and spatial items with named procedures; prepare honestly for a paper psikotes; choose pacing and guessing rules from a test’s scoring rule, including a 110-item computer-assisted test; answer personality, values and situational-judgement items consistently; and follow a three-week plan driven by the Lab’s error log and weakness map.', 'Di akhir modul ini kamu bisa mengenali tes yang kemungkinan dipakai sebuah program dan mengarahkan diri ke jalur yang tepat; menyelesaikan soal numerik, verbal, penalaran, figural, dan spasial dengan prosedur bernama; bersiap jujur untuk psikotes kertas; memilih aturan tempo dan menebak dari aturan penilaian tes, termasuk tes berbantuan komputer 110 soal; menjawab soal kepribadian, nilai, dan penilaian situasional secara konsisten; dan mengikuti rencana tiga minggu yang digerakkan catatan kesalahan dan peta kelemahan Lab.'),
  dossier: b('Baseline profile and weakness map · Error log · 3-week plan · Test-day checklist', 'Profil awal dan peta kelemahan · Catatan kesalahan · Rencana 3 minggu · Daftar periksa hari tes')
};

module.exports = { RENUMBER, L74, L76, PATCH, MODULE };
